/**
 * Production UI check: logs into the deployed instance with the credentials
 * generated by test/prod-smoke.mjs and captures a screenshot.
 *
 *   QEXO_BASE_URL=<deployment-url> node test/prod-ui.mjs
 */

import fs from "node:fs";
import { chromium } from "playwright-core";

// Deployment URL is never stored in the repo: pass it as argv[2] or QEXO_BASE_URL.
const BASE = (process.argv[2] || process.env.QEXO_BASE_URL || "https://qexo.example.com").replace(/\/+$/, "");
const EDGE = "C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe";
const CRED = "test/out/deploy-credentials.txt";

if (!fs.existsSync(CRED)) {
  console.error("missing credentials; run test/prod-smoke.mjs first");
  process.exit(1);
}
const text = fs.readFileSync(CRED, "utf8");
const username = /username=(.+)/.exec(text)?.[1]?.trim();
const password = /password=(.+)/.exec(text)?.[1]?.trim();
if (!username || !password) {
  console.error("credentials file is incomplete");
  process.exit(1);
}

const errors = [];
const browser = await chromium.launch({ executablePath: EDGE, headless: true });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.on("pageerror", (e) => errors.push(String(e)));
page.on("console", (m) => {
  if (m.type() === "error") errors.push(m.text());
});

let failures = 0;
async function step(name, fn) {
  try {
    const detail = await fn();
    console.log(`  ✓ ${name}${detail ? ` — ${detail}` : ""}`);
  } catch (e) {
    failures++;
    console.error(`  ✗ ${name} — ${e.message}`);
  }
}

console.log(`\nQexo production UI → ${BASE}\n${"=".repeat(56)}`);

await step("登录页", async () => {
  await page.goto(BASE + "/#/login", { waitUntil: "networkidle" });
  await page.waitForSelector("#login-form");
  return await page.textContent(".auth-head h2");
});

await step("登录并进入控制台", async () => {
  await page.fill('#login-form input[name="username"]', username);
  await page.fill('#login-form input[name="password"]', password);
  await page.click("#login-btn");
  await page.waitForFunction(() => location.hash === "#/dashboard", null, { timeout: 20000 });
  await page.waitForSelector(".stat");
  const pill = await page.textContent("#provider-pill");
  const version = (await page.textContent("#version")) || "";
  if (!version.includes("1.4.0")) throw new Error(`unexpected UI version: ${version}`);
  return `${pill.trim()} · ${version.trim()}`;
});

await step("控制台截图", async () => {
  await page.screenshot({ path: "test/out/prod-dashboard.png", fullPage: true });
  const cards = await page.$$(".stat");
  if (cards.length !== 4) throw new Error(`expected 4 cards, got ${cards.length}`);
  return "4 cards";
});

await step("内容源表单：PAT 链接与下拉", async () => {
  await page.goto(BASE + "/#/settings/provider");
  await page.waitForSelector("#gh-pat-link");
  const href = await page.getAttribute("#gh-pat-link", "href");
  if (!href.startsWith("https://github.com/settings/personal-access-tokens/new?")) throw new Error(`PAT href=${href}`);
  const target = new URL(href);
  if (target.searchParams.get("contents") !== "write") throw new Error(`contents=${target.searchParams.get("contents")}`);
  if (target.searchParams.get("expires_in") !== "90") throw new Error(`expires_in=${target.searchParams.get("expires_in")}`);
  if ((await page.getAttribute("#gh-pat-link", "target")) !== "_blank") throw new Error("PAT link must open a new tab");
  const rel = (await page.getAttribute("#gh-pat-link", "rel")) || "";
  if (!rel.includes("noopener")) throw new Error(`rel=${rel}`);
  const why = (await page.textContent(".pat-why")) || "";
  if (!why.includes("只覆盖")) throw new Error("missing least-privilege explanation");
  const tags = await page.evaluate(() => ({
    repo: document.getElementById("gh-repo")?.tagName,
    branch: document.getElementById("gh-branch")?.tagName,
  }));
  if (tags.repo !== "SELECT" || tags.branch !== "SELECT") throw new Error(JSON.stringify(tags));
  const savedRepo = await page.inputValue("#gh-repo");
  const savedBranch = await page.inputValue("#gh-branch");
  const hasSavedInfo = !!(await page.$("#gh-saved-info"));
  if (hasSavedInfo) {
    if (!savedRepo.includes("/")) throw new Error(`saved repo not prefilled: ${savedRepo}`);
    if (!savedBranch) throw new Error("saved branch not prefilled");
    const saved = (await page.textContent("#gh-saved-info")) || "";
    if (!saved.includes("已自动回填")) throw new Error(`saved info=${saved}`);
  } else if (savedRepo || savedBranch) {
    throw new Error("unexpected prefilled values without saved info");
  }
  const repoPlaceholder = (await page.textContent('#gh-repo option[value=""]')) || "";
  if (!repoPlaceholder.includes("必填")) throw new Error(`repo placeholder=${repoPlaceholder}`);
  await page
    .waitForFunction(
      () => {
        const el = document.getElementById("gh-repo-status");
        return el && (el.classList.contains("ok") || el.classList.contains("err"));
      },
      { timeout: 30000 },
    )
    .catch(() => {});
  const status = (await page.textContent("#gh-repo-status"))?.trim() || "";
  if (!status) throw new Error("empty repository status");
  await page.evaluate(() => window.scrollTo(0, 0));
  await page.waitForTimeout(250);
  await page.screenshot({ path: "test/out/prod-settings.png", fullPage: true });
  return `${status.slice(0, 36)}`;
});

await step("内容源表单：清空仓库后保存被明确拦截", async () => {
  await page.selectOption("#gh-repo", "");
  await page.click("#save-provider");
  const msg = (await page.textContent("#prov-msg")) || "";
  if (!msg.includes("仓库为空")) throw new Error(msg);
  return msg.slice(0, 44);
});

await step("内容源表单：密钥状态提示", async () => {
  const token = await page.inputValue("#gh-token");
  if (token) {
    // A real token is configured: the page auto-runs the health check. Accept
    // either a successful listing or a clear upstream error (rate limit/401).
    await page.waitForFunction(
      () => {
        const el = document.getElementById("gh-repo-status");
        return el && (el.classList.contains("ok") || el.classList.contains("err"));
      },
      { timeout: 30000 },
    );
    const text = (await page.textContent("#gh-repo-status")) || "";
    if (!/已连接|读取仓库失败|暂无/.test(text)) throw new Error(text);
    return text.trim().slice(0, 40);
  }
  await page.click("#gh-check");
  await page.waitForFunction(
    () => document.getElementById("gh-token-status")?.classList.contains("err"),
    { timeout: 15000 },
  );
  const text = (await page.textContent("#gh-token-status")) || "";
  if (!/密钥/.test(text)) throw new Error(text);
  for (let i = errors.length - 1; i >= 0; i--) {
    if (/status of 400/.test(errors[i])) errors.splice(i, 1);
  }
  return text.trim().slice(0, 40);
});

await step("MCP 页面", async () => {
  await page.goto(BASE + "/#/mcp");
  await page.waitForSelector("#new-token");
  const text = await page.textContent("#view");
  if (!text.includes("Streamable HTTP")) throw new Error("MCP page content missing");
  if (!text.includes("Agent 提示词结构规范")) throw new Error("agent prompt spec missing");
  await page.screenshot({ path: "test/out/prod-mcp.png", fullPage: true });
  return "endpoint + tools listed";
});

await step("无 JS 运行时错误", async () => {
  const filtered = errors.filter((e) => !/favicon|fonts\.googleapis|403|rate limit/i.test(e));
  if (filtered.length) throw new Error(filtered.join("\n"));
  return `${errors.length} console messages`;
});

console.log("=".repeat(56));
console.log(failures ? `${failures} failed` : "all checks passed");
await browser.close();
process.exit(failures ? 1 : 0);
